using System.IO.Compression;using Orbit.Core;
static class ClasspathChecks {
 public static int Run(string root,string probe){try{var settings=new LauncherSettings{GameRoot=root,Nickname="OrbitTester"};var plan=LaunchEngine.Build(settings,"1.12.2");if(plan.Missing.Count>0)throw new Exception(string.Join(";",plan.Missing));int index=plan.Arguments.IndexOf("-cp");if(index<0)throw new Exception("Classpath missing");string cp=plan.Arguments[index+1];var jars=cp.Split(Path.PathSeparator);bool Has(string name)=>jars.Any(p=>{using var zip=ZipFile.OpenRead(p);return zip.GetEntry(name)!=null;});
 if(!Has("org/lwjgl/LWJGLException.class")||!Has("org/lwjgl/util/vector/Vector3f.class"))throw new Exception("Required LWJGL class missing from launch classpath");if(jars.Any(p=>p.Contains("2.9.2-nightly-20140822")))throw new Exception("macOS dependency included on Windows");
 var check=new LaunchPlan{Version=plan.Version,Java=plan.Java,GameDirectory=probe,Natives=Path.Combine(probe,"natives")};check.Arguments.AddRange(new[]{"-cp",probe+Path.PathSeparator+cp,"OrbitClasspathProbe"});using var process=LaunchEngine.Start(check);string output=process.StandardOutput.ReadToEnd(),error=process.StandardError.ReadToEnd();process.WaitForExit();Console.Write(output);if(process.ExitCode!=0)throw new Exception(error);if(!output.Contains("PASS org.lwjgl.LWJGLException")||!output.Contains("PASS net.minecraft.client.main.Main"))throw new Exception("Java probe incomplete");Console.WriteLine("PASS actual Minecraft 1.12.2 launch classpath on Java 8; game not started");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
